test('API-01: POST /api/todos uses medium priority by default', async () => {
  const res = await fetch(`${BASE_URL}/api/todos`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'Default priority task' })
  });
  assert.strictEqual(res.status, 201);
  const data = await res.json();
  assert.strictEqual(data.priority, 'medium');
});

test('API-01: POST /api/todos accepts low, medium, high priorities', async () => {
  for (const priority of ['low', 'medium', 'high']) {
    const res = await fetch(`${BASE_URL}/api/todos`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: `Task with ${priority}`, priority })
    });
    assert.strictEqual(res.status, 201);
    const data = await res.json();
    assert.strictEqual(data.priority, priority);
  }
});

test('API-01: POST /api/todos rejects invalid priority with 400', async () => {
  for (const priority of ['urgent', 1, null, 'HIGH']) {
    const res = await fetch(`${BASE_URL}/api/todos`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: 'Bad priority task', priority })
    });
    assert.strictEqual(res.status, 400, `Expected 400 for priority: ${JSON.stringify(priority)}`);
  }
});

test('API-02: PUT /api/todos/:id can change priority', async () => {
  const createRes = await fetch(`${BASE_URL}/api/todos`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'Priority update test', priority: 'low' })
  });
  const created = await createRes.json();

  const updateRes = await fetch(`${BASE_URL}/api/todos/${created.id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ priority: 'high' })
  });
  assert.strictEqual(updateRes.status, 200);
  const updated = await updateRes.json();
  assert.strictEqual(updated.priority, 'high');
});

test('API-02: PUT /api/todos/:id rejects invalid priority with 400 and changes nothing', async () => {
  const createRes = await fetch(`${BASE_URL}/api/todos`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'PUT invalid priority test', priority: 'low' })
  });
  const created = await createRes.json();

  const updateRes = await fetch(`${BASE_URL}/api/todos/${created.id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ priority: 'critical', completed: true })
  });
  assert.strictEqual(updateRes.status, 400);

  const listRes = await fetch(`${BASE_URL}/api/todos`);
  const todos = await listRes.json();
  const saved = todos.find(t => t.id === created.id);
  assert.strictEqual(saved.priority, 'low');
  assert.strictEqual(saved.completed, false);
});

test('API-03: GET /api/todos includes priority on all todos', async () => {
  const res = await fetch(`${BASE_URL}/api/todos`);
  assert.strictEqual(res.status, 200);
  const data = await res.json();
  assert.ok(data.length > 0);
  for (const todo of data) {
    assert.ok(['low', 'medium', 'high'].includes(todo.priority), `Todo ${todo.id} missing valid priority`);
  }
});

